/**
 * Schema for the get_design_rules tool — returns rules for reproducing
 * coded UIs in Figma by reading CSS and matching styles exactly.
 */
export const getDesignRulesSchema = {
    name: 'get_design_rules',
    description: `Get rules for code-to-Figma reproduction.
ALWAYS call this BEFORE recreating any existing app screen or component in Figma.
The process is: read the CSS/code first, then reproduce each element in Figma matching the exact values.
Returns rules for the requested topic covering the overall process, CSS-to-Figma mapping, text handling, limitations, and verification.`,
    inputSchema: {
        type: 'object',
        properties: {
            topic: {
                type: 'string',
                description: 'Topic to get rules for. Use "all" for complete guide.',
                enum: ['all', 'process', 'css-mapping', 'text', 'layout', 'components', 'limitations'],
                default: 'all',
            },
        },
    },
};
